import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import '../styles/RegisterPage.css';

const RegisterPage = () => {
    const [formData, setFormData] = useState({
        name: '',
        email: '',
        password: '',
        confirmPassword: '',
        agree: false
    });
    const [showPassword, setShowPassword] = useState(false);
    const [showConfirmPassword, setShowConfirmPassword] = useState(false);
    const [errors, setErrors] = useState({});
    const navigate = useNavigate();

    const togglePasswordVisibility = (field) => {
        if (field === 'password') {
            setShowPassword(!showPassword);
        } else if (field === 'confirmPassword') {
            setShowConfirmPassword(!showConfirmPassword);
        }
    };

    const isValidEmail = (email) => {
        const regex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return regex.test(email);
    };

    const validateForm = () => {
        const newErrors = {};
        
        if (!formData.name.trim()) {
            newErrors.name = "Ім'я обов'язкове";
        }
        
        if (!formData.email.trim()) {
            newErrors.email = "Email обов'язковий";
        } else if (!isValidEmail(formData.email)) {
            newErrors.email = "Невірний формат email";
        }
        
        if (!formData.password) {
            newErrors.password = "Пароль обов'язковий";
        } else if (formData.password.length < 6) {
            newErrors.password = "Пароль повинен містити щонайменше 6 символів";
        }
        
        if (!formData.confirmPassword) {
            newErrors.confirmPassword = "Підтвердження пароля обов'язкове";
        } else if (formData.password !== formData.confirmPassword) {
            newErrors.confirmPassword = "Паролі не співпадають";
        }
        
        if (!formData.agree) {
            newErrors.agree = "Потрібно погодитися з політикою конфіденційності";
        }
        
        setErrors(newErrors);
        return Object.keys(newErrors).length === 0;
    };

    const handleChange = (e) => {
        const { name, value, type, checked } = e.target;
        setFormData({
            ...formData,
            [name]: type === 'checkbox' ? checked : value
        });
        
        // Очищаем ошибку при изменении поля
        if (errors[name]) {
            setErrors({
                ...errors,
                [name]: null
            });
        }
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        
        if (validateForm()) {
            // Здесь можно добавить логику отправки данных на сервер
            alert("Реєстрація пройшла успішно!");
            // Перенаправление на главную страницу после успешной регистрации
            navigate('/');
        }
    };

    const goBack = () => {
        navigate('/');
    };

    return (
        <div className="register-page">
            <a href="#" className="back" onClick={goBack}>← Назад</a>
            <div className="form-container">
                <h2>Реєстрація</h2>
                <form onSubmit={handleSubmit}>
                    <input
                        type="text"
                        name="name"
                        placeholder="Джон Сміт"
                        value={formData.name}
                        onChange={handleChange}
                        className={errors.name ? 'invalid' : ''}
                    />
                    <input
                        type="email"
                        name="email"
                        placeholder="fyybuyunnymyu@gmail.com"
                        value={formData.email}
                        onChange={handleChange}
                        className={errors.email ? 'invalid' : ''}
                    />
                    <div className="password-field">
                        <input
                            type={showPassword ? "text" : "password"}
                            name="password"
                            placeholder="123456"
                            value={formData.password}
                            onChange={handleChange}
                            className={errors.password ? 'invalid' : ''}
                        />
                        <span onClick={() => togglePasswordVisibility('password')}>
                            {showPassword ? '🙈' : '👁️'}
                        </span>
                    </div>
                    <div className="password-field">
                        <input
                            type={showConfirmPassword ? "text" : "password"}
                            name="confirmPassword"
                            placeholder="Підтвердіть пароль"
                            value={formData.confirmPassword}
                            onChange={handleChange}
                            className={errors.confirmPassword ? 'invalid' : ''}
                        />
                        <span onClick={() => togglePasswordVisibility('confirmPassword')}>
                            {showConfirmPassword ? '🙈' : '👁️'}
                        </span>
                    </div>
                    <div className="checkbox">
                        <input
                            type="checkbox"
                            name="agree"
                            id="agree"
                            checked={formData.agree}
                            onChange={handleChange}
                        />
                        <label htmlFor="agree">Я приймаю <a href="#">Політика конфіденційності</a></label>
                    </div>
                    {errors.agree && <div className="error-message">{errors.agree}</div>}
                    <button type="submit">Зареєструватись</button>
                </form>
                <div className="or"><span>Або</span></div>
                <div className="social-btns">
                    <button>
                        <img src="https://www.svgrepo.com/show/475656/google-color.svg" alt="G" />
                        Продовжити з Google
                    </button>
                    <button>
                        <img src="https://www.svgrepo.com/show/475647/facebook-color.svg" alt="FB" />
                        Продовжити з Facebook
                    </button>
                </div>
            </div>
        </div>
    );
};

export default RegisterPage;
